 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {x for row in grid for x in row}
    # Find the repeated lattice-line color.
    def score(c):
        return sum(sum(x == c for x in row) / w >= .7 for row in grid) + sum(sum(grid[r][j] == c for r in range(h)) / h >= .7 for j in range(w))
    line = max(colors, key=score)
    rs = [r for r in range(h) if sum(x == line for x in grid[r]) / w >= .7]
    cs = [c for c in range(w) if sum(grid[r][c] == line for r in range(h)) / h >= .7]
    if len(rs) < 2 or len(cs) < 2:
        return grid
    bg = max(colors - {line}, key=lambda c: sum(x == c for row in grid for x in row))
    # Marker boundary coordinates are grouped in adjacent pairs; each pair
    # denotes one output column, with blank output columns between groups.
    marked = [c for c in cs if any(grid[r][c] != line for r in rs)]
    groups = []
    for c in marked:
        if groups and c == groups[-1][-1] + 1:
            groups[-1].append(c)
        else:
            groups.append([c])
    # If lattice-line coordinates are regularly spaced, paired markers may be
    # separated by one lattice interval rather than physically adjacent.
    if len(groups) == 1 and len(marked) > 1:
        groups = [marked[i:i+2] for i in range(0, len(marked), 2)]
    if not groups:
        return [[bg]]
    out = []
    for r0, r1 in zip(rs, rs[1:]):
        vals = []
        for gi, g in enumerate(groups):
            if gi:
                vals.append(bg)
            samples = [grid[r][c] for r in (r0, r1) for c in g]
            v = samples[0]
            vals.append(v if v != line and all(x == v for x in samples) else bg)
        out.append(vals)
    # Crop blank top/bottom rows only; retain interior blank rows/columns.
    active = [i for i,row in enumerate(out) if any(x != bg for x in row)]
    return [out[i] for i in range(active[0]:active[-1]+1)] if active else [[bg]]
