        if regular(rs) and regular(cs):
            candidates.append((len(rs) + len(cs), color, rs, cs))
    if not candidates:
        return grid
    _, line, rs, cs = max(candidates)
    bg = max(colors - {line}, key=lambda c: sum(v == c for row in grid for v in row))

    marked = [c for c in cs if any(grid[r][c] != line for r in rs)]
    groups = [marked[i:i + 2] for i in range(0, len(marked), 2)]
    if not groups:
        return [[bg]]

    out = []
